package com.mynikatech.memgine.poynt.auth;
import android.content.Context; public final class StaffSessionStore extends EncryptedPreferenceStore { private static final String TOKEN="session_token", STAFF_ID="staff_id"; public StaffSessionStore(Context context){super(context,"memgine_staff_session");} public String token(){return preferences.getString(TOKEN,null);} public String staffId(){return preferences.getString(STAFF_ID,null);} public void save(String token,String staffId){preferences.edit().putString(TOKEN,token).putString(STAFF_ID,staffId).apply();} public void clear(){preferences.edit().clear().apply();} }
